import { fraction } from '../../features/unit-v2/math/fraction.ts'
import type { ChallengeItem, DiagnosticQuestion, ExerciseSection, LocalizedText, PracticeItem } from '../../features/unit-v2/types.ts'

/* ==========================================================================
   Sistemak · Batxilergoa 2 · Zientziak — diagnostic, guided practice,
   exercise bank and challenges, with the scope of unit 3 of Santillana 2.º
   Bachillerato Ciencias and unit 3 of Anaya Matemáticas II, and the style
   of the Basque university entrance exams (discuss with a parameter and
   solve by Cramer). All the exercises and numbers are ours. Every closed
   answer is a single number: an unknown, a rank, a number of parameters,
   a value of the parameter. The type of a system is asked with options
   (diagnostic and «Check it»).
   ========================================================================== */

const say = (eu: string, es: string, ar: string, en: string): LocalizedText => ({ eu, es, en, ar: ar.replace(/\{,\}/g, '.') })
const same = (value: string): LocalizedText => ({ eu: value, es: value, en: value, ar: value.replace(/\{,\}/g, '.') })
const n = (value: number, denominator = 1) => fraction(value, denominator)

const SCD = say('Bateragarri determinatua', 'Compatible determinado', 'متوافق محدد', 'Consistent and independent')
const SCI = say('Bateragarri indeterminatua', 'Compatible indeterminado', 'متوافق غير محدد', 'Consistent and dependent')
const SI = say('Bateraezina', 'Incompatible', 'غير متوافق', 'Inconsistent')

/** «Solve … by Cramer and give x» */
const cramerFor = (system: string, unknown: string) => say(unknown === 'z' ? `Ebatzi Cramerren bidez ${system}, eta eman hirugarren ezezagunaren balioa.` : `Ebatzi Cramerren bidez ${system}, eta eman $${unknown}$.`, `Resuelve por Cramer ${system} y da $${unknown}$.`, `حُلّ بطريقة كرامر ${system} وأعطِ $${unknown}$.`, `Solve by Cramer ${system} and give $${unknown}$.`)
/** «For which a does … have non-trivial solutions?» */
const nonTrivial = (letter: string, system: string) => say(`Zein $${letter}$ baliotarako ditu soluzio ez-tribialak ${system} sistemak?`, `¿Para qué $${letter}$ tiene soluciones no triviales ${system}?`, `لأي $${letter}$ يكون لـ ${system} حلول غير بديهية؟`, `For which $${letter}$ does ${system} have non-trivial solutions?`)

